@staticmethod
def find_device_by_id(data: Dict[str, Any], device_id: str) -> str:
    """
    Find a device by its unique identifier.

    Args:
        data: The data dictionary containing devices
        device_id: The unique identifier of the device to search for

    Returns:
        A JSON string with the device information
    """
    if not device_id:
        return json.dumps({
            "success": False,
            "message": "No device ID specified"
        })

    # Get the current user's home ID
    home_id = get_user_home_id(data)

    # Search for the device by ID
    for device in data["devices"]:
        if device["home_id"] == home_id and device["id"] == device_id:
            return json.dumps({
                "success": True,
                "device": device
            })

    return json.dumps({
        "success": False,
        "message": f"Device with ID '{device_id}' not found"
    })

@staticmethod
def find_devices_by_type(data: Dict[str, Any], device_type: str) -> str:
    """
    Find all devices of a specific type in the user's home.

    Args:
        data: The data dictionary containing devices
        device_type: The type of devices to search for (e.g., "light", "thermostat", "speaker")

    Returns:
        A JSON string with a list of matching devices
    """
    if not device_type:
        return json.dumps({
            "success": False,
            "message": "No device type specified"
        })

    # Get the current user's home ID
    home_id = get_user_home_id(data)

    # Search for devices by type
    matching_devices = []
    for device in data["devices"]:
        if device["home_id"] == home_id and device["type"].lower() == device_type.lower():
            matching_devices.append(device)

    if matching_devices:
        return json.dumps({
            "success": True,
            "devices": matching_devices,
            "count": len(matching_devices)
        })
    else:
        return json.dumps({
            "success": False,
            "message": f"No devices of type '{device_type}' found"
        })
```

